// Helpers 8: map[string]*Child.
func (h dtogen) clone8(v map[string]*Child) map[string]*Child {
	if v == nil {
		return nil
	}
	out := make(map[string]*Child, len(v))
	for k, x := range v {
		out[k] = h.clone9(x)
	}
	return out
}
func (h dtogen) equal8(v, w map[string]*Child) bool {
	if len(v) != len(w) {
		return false
	}
	for k, x := range v {
		y, ok := w[k]
		if !ok || !h.equal9(x, y) {
			return false
		}
	}
	return true
}
func (h dtogen) check8(v map[string]*Child, b *dtogenCodec.Budget, d, cap int) (err error) {
	if err := b.CheckMap(len(v), d, cap); err != nil {
		return err
	}
	for k, x := range v {
		if err := h.check5(k, b, d+1, int(^uint(0)>>1)); err != nil {
			return err
		}
		if err := h.check9(x, b, d+1, int(^uint(0)>>1)); err != nil {
			return err
		}
	}
	return nil
}
func (h dtogen) append8(out []byte, v map[string]*Child) []byte {
	keys := make([]string, 0, len(v))
	for k := range v {
		keys = append(keys, k)
	}
	dtogenSlices.SortFunc(keys, func(a, b string) int {
		if len(a) != len(b) {
			return len(a) - len(b)
		}
		if a < b {
			return -1
		}
		if a > b {
			return 1
		}
		return 0
	})
	out = dtogenCBOR.AppendMapHeader(out, uint64(len(v)))
	for _, k := range keys {
		out = dtogenCBOR.AppendText(out, string(k))
		out = h.append9(out, v[k])
	}
	return out
}
func (h dtogen) read8(r *dtogenCodec.Reader, d, cap int) (v map[string]*Child, err error) {
	count, err := r.Map(d, cap)
	if err != nil {
		return v, err
	}
	v = make(map[string]*Child, count)
	previous := ""
	for i := 0; i < count; i++ {
		k, err := h.read5(r, d+1, int(^uint(0)>>1))
		if err != nil {
			return v, err
		}
		key := string(k)
		// Strict canonical key ordering also rejects duplicates before assignment can overwrite them.
		if i > 0 && (len(key) < len(previous) || (len(key) == len(previous) && key <= previous)) {
			return v, dtogenCodec.ErrInvalidData
		}
		previous = key
		x, err := h.read9(r, d+1, int(^uint(0)>>1))
		if err != nil {
			return v, err
		}
		v[k] = x
	}
	return v, nil
}

