// Helpers 10: Child.
func (h dtogen) clone10(v Child) Child {
	out := v
	out.Label = h.clone5(v.Label)
	out.Data = h.clone11(v.Data)
	out.Children = h.clone13(v.Children)
	return out
}
func (h dtogen) equal10(v, w Child) bool {
	if !h.equal5(v.Label, w.Label) {
		return false
	}
	if !h.equal11(v.Data, w.Data) {
		return false
	}
	if !h.equal13(v.Children, w.Children) {
		return false
	}
	return true
}
func (h dtogen) check10(v Child, b *dtogenCodec.Budget, d, cap int) (err error) {
	count := 3
	if err := b.CheckMap(count, d, cap); err != nil {
		return err
	}
	if err := b.CheckString("c", d+1, int(^uint(0)>>1)); err != nil {
		return dtogenFmt.Errorf("Children: %w", err)
	}
	if err := h.check13(v.Children, b, d+1, int(^uint(0)>>1)); err != nil {
		return dtogenFmt.Errorf("Children: %w", err)
	}
	if err := b.CheckString("d", d+1, int(^uint(0)>>1)); err != nil {
		return dtogenFmt.Errorf("Data: %w", err)
	}
	if err := h.check11(v.Data, b, d+1, int(^uint(0)>>1)); err != nil {
		return dtogenFmt.Errorf("Data: %w", err)
	}
	if err := b.CheckString("l", d+1, int(^uint(0)>>1)); err != nil {
		return dtogenFmt.Errorf("Label: %w", err)
	}
	if err := h.check5(v.Label, b, d+1, int(^uint(0)>>1)); err != nil {
		return dtogenFmt.Errorf("Label: %w", err)
	}
	return nil
}
func (h dtogen) append10(out []byte, v Child) []byte {
	count := 3
	out = dtogenCBOR.AppendMapHeader(out, uint64(count))
	out = dtogenCBOR.AppendText(out, "c")
	out = h.append13(out, v.Children)
	out = dtogenCBOR.AppendText(out, "d")
	out = h.append11(out, v.Data)
	out = dtogenCBOR.AppendText(out, "l")
	out = h.append5(out, v.Label)
	return out
}
func (h dtogen) read10(r *dtogenCodec.Reader, d, cap int) (v Child, err error) {
	count, err := r.Map(d, cap)
	if err != nil {
		return v, err
	}
	previous := ""
	var seen [3]bool
	for i := 0; i < count; i++ {
		key, err := r.String(d+1, int(^uint(0)>>1))
		if err != nil {
			return v, err
		}
		// Strict canonical key ordering also rejects duplicates before assignment can overwrite them.
		if i > 0 && (len(key) < len(previous) || (len(key) == len(previous) && key <= previous)) {
			return v, dtogenCodec.ErrInvalidData
		}
		previous = key
		switch key {
		case "c":
			seen[0] = true
			v.Children, err = h.read13(r, d+1, int(^uint(0)>>1))
			if err != nil {
				return v, dtogenFmt.Errorf("Children: %w", err)
			}
		case "d":
			seen[1] = true
			v.Data, err = h.read11(r, d+1, int(^uint(0)>>1))
			if err != nil {
				return v, dtogenFmt.Errorf("Data: %w", err)
			}
		case "l":
			seen[2] = true
			v.Label, err = h.read5(r, d+1, int(^uint(0)>>1))
			if err != nil {
				return v, dtogenFmt.Errorf("Label: %w", err)
			}
		default:
			return v, dtogenCodec.ErrInvalidData
		}
	}
	if !seen[0] {
		return v, dtogenCodec.ErrInvalidData
	}
	if !seen[1] {
		return v, dtogenCodec.ErrInvalidData
	}
	if !seen[2] {
		return v, dtogenCodec.ErrInvalidData
	}
	return v, nil
}

